import {escapeHTML as h,markdown} from './markdown.js';
import {STORAGE_KEY,initialState,restoreState,getDraft,newEntry,nextDayCycle,exportDraft,targetType,selectActual} from './model.js';
const $=s=>document.querySelector(s);
const icons={book:'<path d="M4 3h6a3 3 0 0 1 3 3v15a4 4 0 0 0-4-2H4z"/><path d="M20 3h-4a3 3 0 0 0-3 3v15a4 4 0 0 1 4-2h3z"/>',moon:'<path d="M20 14A8 8 0 0 1 10 4a8 8 0 1 0 10 10Z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>',target:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3"/>',dawn:'<path d="M3 17h18M5 21h14M12 3v3M4 7l2 2m12 0 2-2M6 17a6 6 0 0 1 12 0"/>',chat:'<path d="M21 11a8 8 0 0 1-8 8H6l-4 3 1-7a8 8 0 1 1 18-4Z"/><path d="M7 9h10M7 13h6"/>',next:'<path d="M4 12h15m-5-5 5 5-5 5"/>',check:'<path d="m5 12 4 4L19 6"/>',warning:'<path d="m12 3 10 18H2Z"/><path d="M12 9v5m0 3v.1"/>',edit:'<path d="M15 4l5 5M4 20l5-1L21 7a2 2 0 0 0-5-5L4 14Z"/>',chevron:'<path d="m8 5 7 7-7 7"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',trash:'<path d="M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.book}</svg>`;
let data,roles,library,byId,state,pickerMode='actual',pickerOpener=null,toastTimer,storageFailure=false,saveTimer;
const colors=role=>role.alignment.startsWith('Coven')?['#c4a2eb','#30273f']:role.alignment==='Neutral Apocalypse'?['#e3a398','#39282b']:role.alignment.startsWith('Town')?['#8bc6aa','#1e342c']:['#d8bb82','#302a20'];
function actual(){return byId.get(state.actualId);}
function base(role=actual()){return role.parentId?byId.get(role.parentId):role;}
function claimed(){return byId.get(state.claimId);}
function currentRole(){return state.namespace==='private'?(byId.get(state.privateViewId)||actual()):claimed();}
function currentDraft(){return getDraft(state,state.namespace,currentRole().id);}
function image(role,className=''){return `<span class="image-wrap"><img class="role-image ${className}" src="${h(role.iconUrl)}" data-fallback="${h(role.iconFallback||'')}" alt="" loading="lazy" width="44" height="44" data-role-name="${h(role.name)}"></span>`;}
function badge(role){return `<span class="badge" title="${h(role.alignment)}">${h(role.alignment_abbreviation)}</span>`;}
function fullAlignment(role){return `${h(role.alignment_abbreviation)}${role.alignment_abbreviation===role.alignment?'':` · ${h(role.alignment)}`}`;}
function isExpanded(id){return state.detail||state.expanded.includes(id);}
function save(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>{try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageFailure=false;}catch{storageFailure=true;}updateSaveStatus();},180);}
function persistNow(){clearTimeout(saveTimer);try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageFailure=false;}catch{storageFailure=true;}updateSaveStatus();}
window.addEventListener('pagehide',()=>state&&persistNow());
function updateSaveStatus(){const el=$('#save-state');if(el)el.textContent=storageFailure?'In memory · copy to keep a backup':'Saved on this browser';}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,3200);}
function cardOf(role,key){return base(role).cards.find(c=>c.id.endsWith('-'+key));}
function toggleButton(id){return `<button class="text-button" data-action="detail" data-card="${h(id)}" aria-expanded="${isExpanded(id)}">${isExpanded(id)?'Show less':'Why?'}</button>`;}
const cardTitles={n1:'First night',dawn:'At dawn',disclosure:'What to say',continuation:'Night 2 & beyond',mistakes:'Avoid this',milestones:'Your subgoals',identity:'Know your role',claims:'Claim reasoning',will:'Will format & examples'};
const cardIcons={n1:'target',dawn:'dawn',disclosure:'chat',continuation:'next',milestones:'check',identity:'book',claims:'chat',will:'edit'};
function renderCard(role,key,extra='',prefix=''){
 const c=cardOf(role,key),id=prefix+c.id,expanded=isExpanded(id);
 let compact=key==='n1'&&!prefix?base(role).opening.action+'\n\n**Choose a target:** '+base(role).opening.target:c.compact;
 let expandedCopy=c.expanded;
 if(key==='disclosure'&&!prefix&&!base(role).alignment.startsWith('Town')){
  const cover=claimed();
  compact='Your selected cover is **'+cover.name+' — '+cover.alignment_abbreviation+' ('+cover.alignment+')**. Use that alignment if asked. '+(cover.alignment==='Town Investigative'?'A TI story normally needs the exact role and a compatible result from D2.':'Give the full cover role and compatible history when needed.');
  expandedCopy='**Selected public claim: '+cover.name+' — '+cover.alignment_abbreviation+'.** The role-specific examples below explain starting cover options; follow the selected claim’s own obligations.\n\n'+c.expanded;
 }
 return `<section class="card ${extra} ${expanded?'expanded':''}" id="${h(id)}"><div class="card-heading"><h3>${icon(cardIcons[key])}${cardTitles[key]||h(c.title)}</h3>${toggleButton(id)}</div><div class="card-content">${markdown(expanded?expandedCopy:compact)}</div></section>`;
}
function renderGoals(role){const c=cardOf(role,'milestones'),expanded=isExpanded(c.id),goals=base(role).opening.goals;return `<section class="card goals-card ${expanded?'expanded':''}" id="${c.id}"><div class="card-heading"><h3>${icon('check')}Your subgoals</h3>${toggleButton(c.id)}</div><ul class="goals-list">${goals.map((g,i)=>`<li><label><input type="checkbox" data-goal="${i}" ${state.goals[role.id]?.includes(i)?'checked':''}><span>${h(g)}</span></label></li>`).join('')}</ul>${expanded?`<div class="card-content more-guidance">${markdown(c.expanded)}</div>`:'<p class="goals-footer">Small checkpoints. A reasoned hold counts.</p>'}</section>`;}
function renderRoleGroups(){
 const group=r=>r.alignment.startsWith('Town')?'Town':r.alignment.startsWith('Coven')?'Coven':'Neutral';
 const current=group(actual());
 return `<nav class="role-quick-nav" aria-label="Quick role selection"><span class="eyebrow">CHOOSE YOUR ROLE</span><div class="role-group-buttons">${[['all','All roles'],['Town','Town'],['Coven','Coven'],['Neutral','Neutral']].map(([faction,label])=>{const count=library.filter(r=>faction==='all'||group(r)===faction).length;return `<button class="role-group-button ${faction===current?'current-group':''}" data-action="choose-group" data-faction="${faction}" aria-label="Choose ${label.toLowerCase()} (${count} roles and states)" aria-haspopup="dialog" aria-expanded="false"><span class="faction-dot ${faction.toLowerCase()}" aria-hidden="true"></span>${label}<span class="role-group-count">${count}</span></button>`;}).join('')}</div></nav>`;
}
function renderHero(){const role=actual(),b=base(role),c=cardOf(role,'identity'),expanded=isExpanded(c.id);return `<section class="hero" aria-labelledby="role-title">${image(role,'hero-art')}<div><span class="eyebrow">YOUR ACTUAL ROLE${role.parentId?' · TRANSFORMED':''}</span><h1 id="role-title">${h(role.name)}</h1><div class="role-meta">${badge(role)}<span>${h(role.alignment)}</span><span aria-hidden="true">·</span><span>${h(b.faction)}</span>${role.alignment.endsWith('Outlier')?'<span class="badge neutral">Setup-dependent</span>':''}</div><div class="role-description ${expanded?'card-content':''}" id="${c.id}">${markdown(expanded?c.expanded:c.compact.replace(/ (?:TI|TP|TK|TS|TPow|CPow|CK|CD|CU|NA|NE|NK) — [^.]+\.$/,''))}${toggleButton(c.id)}</div></div><div class="hero-controls"><button class="button" data-action="choose-actual">${icon('search')} Change role</button><small>${library.length} roles & states · searchable</small></div></section>${role.parentId?`<div class="state-callout"><strong>You are ${h(role.name)} now</strong>${h(role.description)}<div class="source-footnote">The ${h(b.name)} opening below is your earlier history. Use ${h(role.name)} actions in private notes; existing drafts are preserved.</div></div>`:''}`;}
function renderClaims(){const role=actual(),b=base(role),cover=claimed(),c=cardOf(role,'claims'),options=b.claim_candidates||[],expanded=isExpanded(c.id);return `<section id="claims"><div class="section-head claims-heading"><h2>Choose your story</h2><div class="claim-selector"><span class="eyebrow">CLAIMING AS</span><button class="button" data-action="choose-claim">${image(cover,'tiny-role')} ${h(cover.name)} ${badge(cover)} ${icon('chevron')}</button></div></div><p class="claims-help">${b.alignment.startsWith('Town')?'Keep an honest history.':'Start with an overlap you can explain.'} Every role is selectable; suggestions are a starting point.</p>${options.length?`<div class="claim-grid ${options.length===3?'three-options':''}">${options.map(o=>{const r=roles.find(x=>x.name===o.role);return `<article class="claim-option ${state.claimId===r.id?'selected':''}"><div class="claim-option-top">${image(r)}<div class="claim-option-info"><h3>${h(r.name)} ${badge(r)}</h3><span class="fit-label">${h(o.fit)}</span></div><button class="button use-claim" data-action="use-claim" data-role="${r.id}" aria-pressed="${state.claimId===r.id}">${state.claimId===r.id?'Selected': 'Use claim'}</button></div><p>${h(o.why)}</p><p class="exposure"><strong>Exposure:</strong> ${h(o.exposure)}</p></article>`;}).join('')}</div>`:`<div class="card"><div class="card-content">${markdown(expanded?c.expanded:c.compact)}</div></div>`}<div class="claim-explainer"><div class="card-heading"><span class="eyebrow">THE LOGIC BEHIND THE CLAIM</span>${toggleButton(c.id)}</div>${expanded?`<div class="card-content">${markdown(c.expanded)}<p><strong>A useful test:</strong> match your real movement, the target’s feedback, what you can know, and what the claim must do next. Matching just one part does not make the story safe.</p></div>`:''}</div><details class="cover-guide" id="cover-guide"><summary>What ${h(cover.name)} must be able to explain <span class="muted">· ${fullAlignment(cover)}</span></summary><div class="cover-content"><p class="cover-banner">CLAIMED ROLE GUIDE · Your actual role is still ${h(role.name)}.</p><div class="support-grid">${['n1','dawn','disclosure','continuation','mistakes','will'].map(k=>renderCard(cover,k,'','cover-')).join('')}</div></div></details></section>`;}
function renderStrategy(){const role=actual(),b=base(role),m=cardOf(role,'mistakes');return `<section id="strategy" aria-label="Quick strategy"><div class="section-head"><h2>Your next good decision</h2><div class="phase-tabs" aria-label="Focus a phase">${[['n1','First night'],['day','Day 2'],['later','Night 2+']].map(([id,label])=>`<button data-action="phase" data-phase="${id}" aria-pressed="${state.phase===id}">${label}</button>`).join('')}</div></div><div class="strategy-top">${renderCard(role,'n1','first-card '+(state.phase==='n1'?'active-phase':''))}${renderGoals(role)}</div><div class="support-grid">${renderCard(role,'dawn',state.phase==='day'?'active-phase':'')}${renderCard(role,'disclosure',state.phase==='day'?'active-phase':'')}${renderCard(role,'continuation',state.phase==='later'?'active-phase':'')}</div><section class="mistake-card" id="${m.id}">${icon('warning')}<div><div class="card-heading"><h3>Avoid the common trap</h3>${toggleButton(m.id)}</div><div class="card-content">${markdown(isExpanded(m.id)?m.expanded:m.compact)}</div></div></section></section>`;}
function render(){
 const role=actual(),[accent,tint]=colors(role);document.documentElement.style.setProperty('--accent',state.theme==='light'?({Town:'#31664e',Coven:'#794ca0',Apocalypse:'#a14d43',Neutral:'#896730'}[base(role).faction]||'#896730'):accent);document.documentElement.style.setProperty('--accent-bg',state.theme==='light'?({Town:'#e4eee5',Coven:'#f0e7f7',Apocalypse:'#f6e6e1',Neutral:'#f1e9d7'}[base(role).faction]||'#f1e9d7'):tint);
 document.documentElement.dataset.theme=state.theme;
 $('#detail-toggle').innerHTML=icon('book')+(state.detail?'Less detail':'More detail');$('#detail-toggle').setAttribute('aria-expanded',String(state.detail));
 $('#theme-toggle').innerHTML=icon(state.theme==='dark'?'sun':'moon');$('#theme-toggle').setAttribute('aria-label',state.theme==='dark'?'Switch to light theme':'Switch to dark theme');
 const oldCover=$('#cover-guide')?.open||false;
 $('#app').innerHTML=renderRoleGroups()+renderHero()+renderStrategy()+renderClaims()+`<details class="will-section" id="will-section" ${state.willOpen?'open':''}><summary class="will-summary"><span class="summary-name">${icon('edit')}<span><strong>Will builder</strong><small>${h(claimed().name)} · public draft · <span id="will-entry-count">${getDraft(state,'public',state.claimId).entries.length}</span> entries</small></span></span><span class="eyebrow">${state.willOpen?'CLOSE':'OPEN'} ${icon('chevron')}</span></summary><div id="will-body" class="will-body"></div></details><p class="source-footnote">Mechanics checked 15 Oct 2026 · Target priorities and claim fits are strategy suggestions. <button class="text-button" data-action="sources">Review sources</button></p>`;
 if(oldCover)$('#cover-guide').open=true;
 renderWill();$('#will-section').addEventListener('toggle',()=>{state.willOpen=$('#will-section').open;save();});
}
const option=(value,current,label=value)=>`<option value="${h(value)}" ${value===current?'selected':''}>${h(label)}</option>`;
function inputField(label,name,value,extra=''){return `<label class="entry-field"><span>${label}</span><input data-field="${name}" value="${h(value)}" ${extra}></label>`;}
function renderRow(e,role){const t=role.template,type=targetType(role,e);let target='';
 if(type==='roles')target=`<select data-field="target" aria-label="Role target">${option('',e.target,'Choose role…')}${library.map(r=>option(r.name,e.target)).join('')}</select>`;
 else if(type==='none'||type==='guesses')target='<input value="No ordinary target" disabled aria-label="No ordinary target">';
 else target=`<input data-field="target" value="${h(type==='corpse'?e.via:e.target)}" ${type==='corpse'?'data-via="true"':''} placeholder="${type==='pair'?'e.g. 4, 9':type==='corpse'||type==='dead'?'Corpse # / role':'Player #'}" aria-label="${type==='pair'?'Target players':type==='dead'||type==='corpse'?'Corpse':'Target player'}">`;
 const actions=[...new Set([...t.actions,e.action])];
 const results=[...new Set([...t.results,'Failed / no result','Manual feedback',...(e.result?[e.result]:[])])];
 return `<div class="will-row" data-entry="${h(e.id)}"><div class="entry-main"><label class="entry-field"><span>Phase</span><select data-field="phase" aria-label="Entry phase">${option('N',e.phase,'Night')}${option('D',e.phase,'Day')}</select></label>${inputField('Cycle','cycle',e.cycle,'type="number" min="1" step="1" aria-label="Cycle number"')}<label class="entry-field action-field"><span>Action</span><select data-field="action" aria-label="Action">${actions.map(a=>option(a,e.action)).join('')}</select></label><label class="entry-field target-field"><span>${type==='pair'?'Players':type==='roles'?'Role':type==='corpse'||type==='dead'?'Corpse':'Target'}</span>${target}</label><label class="entry-field result-field"><span>Result — optional</span><select data-field="result" aria-label="Result">${option('',e.result,'Not recorded')}${results.map(r=>option(r,e.result)).join('')}</select></label><button class="delete-entry" data-action="delete-entry" data-entry-id="${h(e.id)}" aria-label="Delete entry">${icon('trash')}</button></div>${type==='guesses'?`<div class="guess-grid">${[0,1,2].map(i=>`<div class="guess-pair"><label class="entry-field"><span>Player ${i+1}</span><input data-guess="${i}" data-part="player" value="${h(e.guesses?.[i]?.player||'')}" placeholder="Player #"></label><label class="entry-field"><span>Role / alignment guess</span><input data-guess="${i}" data-part="role" value="${h(e.guesses?.[i]?.role||'')}" placeholder="Exact eligible guess"></label></div>`).join('')}</div>`:''}<div class="entry-extra ${type==='corpse'?'corpse':''}">${type==='corpse'?inputField('Destination — if required','target',e.target,'placeholder="Living player #" aria-label="Corpse ability destination"'):''}${inputField('Actual feedback / result names','feedback',e.feedback,'placeholder="Keep the exact feedback"')}${inputField('Notes — included in detailed format','notes',e.notes,'placeholder="Optional context, charges, or progress"')}</div><div class="entry-row-footer"><button class="text-button" data-action="copy-row" data-entry-id="${h(e.id)}">Copy entry</button><span class="entry-warning">${entryWarning(e,role)}</span></div></div>`;
}
function entryWarning(e,role){
 if(role.id==='deputy'&&e.action==='Shoot'&&(e.phase!=='D'||e.cycle<2))return 'Deputy shoots from D2; correct the phase/cycle or record a failed attempt.';
 if(role.id==='vigilante'&&e.action==='Shoot'&&e.cycle===1)return 'A normal Vigilante cannot shoot N1.';
 if(role.id==='doomsayer'&&e.action==='Three guesses'&&e.cycle===1)return 'N1 confirmation is unavailable.';
 if(role.id==='trapper'&&e.action==='Place trap'&&e.cycle===1)return 'A fresh Trapper must Build before Place.';
 if(role.id==='sheriff'&&e.result==='Innocent')return 'Innocent is not confirmed Town.';
 return '';
}
function renderWill(){const role=currentRole(),draft=currentDraft(),c=cardOf(actual(),'will'),privateMode=state.namespace==='private';
 $('#will-body').innerHTML=`<div class="will-toolbar"><div class="segmented" aria-label="Draft visibility"><button data-action="namespace" data-namespace="public" aria-pressed="${!privateMode}">Public claim draft</button><button data-action="namespace" data-namespace="private" aria-pressed="${privateMode}">Private actual notes</button></div><span class="save-state" id="save-state"></span></div>${privateMode?`<p class="private-notice">Private ${h(role.name)} log. These notes never enter Copy public will. Previous role logs: <select id="private-history" aria-label="Open private role history"><option value="${h(state.actualId)}" ${role.id===state.actualId?'selected':''}>${h(actual().name)} (current)</option>${Object.keys(state.drafts.private).filter(id=>id!==state.actualId).map(id=>`<option value="${h(id)}" ${role.id===id?'selected':''}>${h(byId.get(id)?.name||id)}</option>`).join('')}</select></p>`:`<p class="will-hint">Public role: <strong>${h(role.name)} · ${fullAlignment(role)}</strong>. ${base(actual()).alignment.startsWith('Town')?'Record your actual actions and results.':'Author your cover separately; the template does not perform its ability.'}</p>`}<div class="will-format-row"><label><span>Optional player name or heading</span><input id="draft-title" value="${h(draft.title)}" placeholder="Leave blank for role name only"></label><div class="segmented" aria-label="Will format"><button data-action="format" data-format="short" aria-pressed="${draft.format==='short'}">Short</button><button data-action="format" data-format="detailed" aria-pressed="${draft.format==='detailed'}">Detailed</button></div></div><div class="entries">${draft.entries.length?draft.entries.map(e=>renderRow(e,role)).join(''):'<div class="empty-entries">A fresh page. Add an entry after you decide what to record.</div>'}</div><div class="entry-actions"><button class="button" data-action="add-night">+ Next night</button><button class="button" data-action="add-same">+ Same night</button><button class="button" data-action="add-day">+ Day entry</button></div><div class="preview-heading"><span>${privateMode?'PRIVATE LOG':'PUBLIC WILL'} PREVIEW</span><div class="copy-actions"><button class="button" data-action="copy-template">Blank template</button><button class="button copy-primary" data-action="copy-will">${icon('copy')}${privateMode?'Copy private log':'Copy public will'}</button></div></div><textarea class="will-preview" id="will-preview" readonly aria-label="${privateMode?'Private log':'Public will'} preview" spellcheck="false"></textarea><p class="will-hint" id="preview-note"></p><p class="copy-fallback" id="copy-fallback" hidden>Clipboard access is unavailable. Select the preview text above and copy it.</p><details class="will-guidance" ${isExpanded(c.id)?'open':''}><summary>Format, role restrictions & illustrative example</summary><div class="card-content"><p><strong>${h(role.template.fields)}</strong></p><p>${h(role.template.notes)}</p>${role.template.stateNotes?`<p>${h(role.template.stateNotes)}</p>`:''}<p><strong>Example only — never inserted into your match:</strong></p><pre>${h(role.template.example||'Use the current action and actual feedback; there is no starting-state example for this transformation.')}</pre><p>Failed, unknown, and negative outcomes are different. Keep the actual message; the guide does not decide hidden game outcomes.</p></div></details>`;
 updatePreview();updateSaveStatus();}
function updatePreview(){const exported=exportDraft(state,state.namespace,currentRole());$('#will-preview').value=exported.text;$('#preview-note').textContent=exported.omitted?`${exported.omitted} incomplete ${exported.omitted===1?'entry is':'entries are'} omitted. Add a required target or actual failure feedback. No example values are copied.`:'Copies only this draft. Notes appear in Detailed format; private logs remain separate.';const count=$('#will-entry-count');if(count)count.textContent=getDraft(state,'public',state.claimId).entries.length;}
function pickerFilter(){const query=$('#role-search').value.trim().toLowerCase(),faction=$('#faction-filter').value,alignment=$('#alignment-filter').value;const current=pickerMode==='actual'?state.actualId:state.claimId;const results=library.filter(r=>{
 const b=base(r);const neutral=!b.alignment.startsWith('Town')&&!b.alignment.startsWith('Coven');
 return (faction==='all'||(faction==='Neutral'?neutral:b.faction===faction))&&(alignment==='all'||r.alignment===alignment)&&`${r.name} ${r.alignment} ${r.alignment_abbreviation} ${(r.aliases||[]).join(' ')} ${r.parentId?base(r).name:''}`.toLowerCase().includes(query);
 });
 $('#picker-count').textContent=`${results.length} results`;
 $('#picker-results').innerHTML=results.length?results.map(r=>`<button class="role-result ${current===r.id?'selected':''}" data-action="pick-role" data-role="${r.id}" aria-pressed="${current===r.id}">${image(r)}<span><strong>${h(r.name)}</strong><small>${r.parentId?h(base(r).name)+' transformation':fullAlignment(r)}${r.alignment.endsWith('Outlier')?' · Setup-dependent':''}</small></span></button>`).join(''):'<div class="picker-empty">No roles match. Clear the search or filters to see the full roster.</div>';
 $('#recent-roles').innerHTML=!query&&faction==='all'&&alignment==='all'&&state.recent.length?`<div class="recent-section">RECENT ROLES<div class="recent-list">${state.recent.map(id=>byId.get(id)).map(r=>`<button class="button" data-action="pick-role" data-role="${r.id}">${image(r)}${h(r.name)}</button>`).join('')}</div></div>`:'';
}
function openPicker(mode,opener,faction='all'){pickerMode=mode;pickerOpener=opener;$('#picker-title').textContent=mode==='actual'?'Choose your actual role':'Choose any public claim';$('#picker-help').textContent=mode==='actual'?'Your strategy follows this role. Claim drafts stay separate.':'All roles remain available, including difficult fits. Read the obligations before choosing.';$('#role-search').value='';$('#faction-filter').value=faction;$('#alignment-filter').value='all';pickerFilter();$('#role-picker').showModal();opener?.setAttribute('aria-expanded','true');$('#role-search').focus();}
function closePicker(){if($('#role-picker').open)$('#role-picker').close();}
function useClaim(id){state.claimId=id;state.deliberateClaim=true;save();render();}
function expandCard(id){if(state.detail){state.detail=false;state.expanded=[...document.querySelectorAll('[data-card]')].map(e=>e.dataset.card).filter(x=>x!==id);}else if(state.expanded.includes(id))state.expanded=state.expanded.filter(x=>x!==id);else state.expanded.push(id);save();render();const button=[...document.querySelectorAll('[data-card]')].find(e=>e.dataset.card===id);button?.focus({preventScroll:true});}
function showReference(kind){const area=$('#reference-area');if(!area.hidden&&area.dataset.kind===kind){area.hidden=true;return;}area.dataset.kind=kind;area.hidden=false;
 if(kind==='glossary')area.innerHTML=`<div class="card-heading"><h2>Terms, without the guesswork</h2><button class="text-button" data-action="close-reference">Close</button></div><div class="card-content">${markdown(data.glossary.markdown)}</div>`;
 else {const r=base();area.innerHTML=`<div class="card-heading"><h2>Sources & game artwork</h2><button class="text-button" data-action="close-reference">Close</button></div><div class="card-content"><p>Mechanics checked <strong>15 October 2026</strong> for vanilla text chat with normal factions. Targeting, subgoals, and claim fits are strategic suggestions, not measured success rates. No live-client test is claimed.</p><div class="source-links"><a target="_blank" rel="noopener noreferrer" href="${h(r.source_url)}">${h(r.name)} mechanics</a><a target="_blank" rel="noopener noreferrer" href="${h(r.source_revision_url)}">Reviewed revision</a><a target="_blank" rel="noopener noreferrer" href="${h(actual().iconSource||r.iconSource)}">This role’s artwork source</a><a target="_blank" rel="noopener noreferrer" href="${h(data.sourceSummary.iconRepository)}">Vanilla PNG collection</a></div><p>Town of Salem 2 role art belongs to its respective rights holders. The interface uses actual Vanilla role PNGs from a pinned Fancy UI asset revision, with source-linked original artwork for Oracle, Catalyst, and Cultist. Oracle’s original PNG is bundled with this site for reliable loading. Pilgrim and Covenite use their faction icons. Game artwork is not generated. Role labels remain usable if an image fails.</p><details><summary>Source disagreements & limits</summary>${markdown(data.sourceSummary.uncertaintiesMarkdown)}</details></div>`;}
 area.scrollIntoView({behavior:'smooth',block:'start'});area.focus({preventScroll:true});}
async function copy(text){try{await navigator.clipboard.writeText(text);toast(state.namespace==='private'?'Private log copied':'Public draft copied');}catch{$('#copy-fallback').hidden=false;$('#will-preview').value=text;$('#will-preview').focus();$('#will-preview').select();toast('Select the preview text to copy it');}}
function addEntry(phase,same=false){const draft=currentDraft(),entry=newEntry(draft,currentRole(),phase,same);if(phase==='D')entry.cycle=nextDayCycle({...draft,entries:draft.entries.filter(e=>e.id!==entry.id)});save();renderWill();document.querySelector(`[data-entry="${entry.id}"] select[data-field="action"]`)?.focus();}
async function handleClick(event){const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;
 if(action==='choose-actual')openPicker('actual',button);
 else if(action==='choose-group')openPicker('actual',button,button.dataset.faction);
 else if(action==='choose-claim')openPicker('claim',button);
 else if(action==='close-picker')closePicker();
 else if(action==='pick-role'){const r=byId.get(button.dataset.role);if(pickerMode==='actual'){selectActual(state,r,library);state.expanded=[];}else{state.claimId=r.id;state.deliberateClaim=true;}const focusSelector=pickerMode==='actual'&&pickerOpener?.dataset.faction?`[data-action="choose-group"][data-faction="${pickerOpener.dataset.faction}"]`:`[data-action="${pickerMode==='actual'?'choose-actual':'choose-claim'}"]`;closePicker();save();render();document.querySelector(focusSelector)?.focus({preventScroll:true});toast(`${r.name} ${pickerMode==='actual'?'guide opened':'selected as public claim'}`);}
 else if(action==='use-claim'){useClaim(button.dataset.role);document.querySelector(`[data-action="use-claim"][data-role="${button.dataset.role}"]`)?.focus({preventScroll:true});}
 else if(action==='detail')expandCard(button.dataset.card);
 else if(action==='phase'){state.phase=button.dataset.phase;save();render();const key=state.phase==='day'?'dawn':state.phase==='later'?'continuation':'n1';document.getElementById(cardOf(actual(),key).id)?.scrollIntoView({behavior:'smooth',block:'nearest'});document.querySelector(`[data-phase="${state.phase}"]`)?.focus({preventScroll:true});}
 else if(action==='toggle-setup'){const note=$('#setup-note');note.hidden=!note.hidden;button.setAttribute('aria-expanded',String(!note.hidden));}
 else if(action==='namespace'){state.namespace=button.dataset.namespace;save();renderWill();document.querySelector(`[data-namespace="${state.namespace}"]`)?.focus({preventScroll:true});}
 else if(action==='format'){currentDraft().format=button.dataset.format;save();renderWill();document.querySelector(`[data-format="${button.dataset.format}"]`)?.focus({preventScroll:true});}
 else if(action==='add-night')addEntry('N');
 else if(action==='add-same')addEntry('N',true);
 else if(action==='add-day')addEntry('D');
 else if(action==='delete-entry'){const draft=currentDraft();draft.entries=draft.entries.filter(e=>e.id!==button.dataset.entryId);save();renderWill();}
 else if(action==='copy-will'){const result=exportDraft(state,state.namespace,currentRole());if(!result.included){toast('Add a complete entry first, or use Blank template.');return;}await copy(result.text);}
 else if(action==='copy-row'){const result=exportDraft(state,state.namespace,currentRole(),{entryId:button.dataset.entryId});if(!result.included){toast('Complete this entry before copying.');return;}await copy(result.text);}
 else if(action==='copy-template'){const r=currentRole();await copy(`${r.name}\n[Day/night]: [action] [required target] — [actual feedback]`);}
 else if(action==='open-reset')$('#reset-dialog').showModal();
 else if(action==='cancel-reset')$('#reset-dialog').close();
 else if(action==='confirm-reset'){const preferences={theme:state.theme,detail:state.detail};state={...initialState(),...preferences};persistNow();$('#reset-dialog').close();render();toast('Fresh match started');}
 else if(action==='glossary'||action==='sources')showReference(action);
 else if(action==='close-reference'){$('#reference-area').hidden=true;document.querySelector(`[data-action="${$('#reference-area').dataset.kind}"]`)?.focus();}
}
function handleInput(event){const el=event.target;if(el.id==='role-search'){pickerFilter();return;}if(el.id==='draft-title'){currentDraft().title=el.value;save();updatePreview();return;}
 const row=el.closest('[data-entry]');if(!row)return;const entry=currentDraft().entries.find(e=>e.id===row.dataset.entry);if(!entry)return;
 if(el.dataset.guess!==undefined){entry.guesses ||= [{player:'',role:''},{player:'',role:''},{player:'',role:''}];entry.guesses[Number(el.dataset.guess)][el.dataset.part]=el.value;}
 else if(el.dataset.field){const field=el.dataset.via?'via':el.dataset.field;entry[field]=field==='cycle'?Math.max(1,Number(el.value)||1):el.value;}
 save();updatePreview();
 const warning=row.querySelector('.entry-warning');if(warning)warning.textContent=entryWarning(entry,currentRole());
}
function handleChange(event){const el=event.target;
 if(el.id==='faction-filter'||el.id==='alignment-filter'){pickerFilter();return;}
 if(el.dataset.goal!==undefined){const goals=new Set(state.goals[state.actualId]||[]);el.checked?goals.add(Number(el.dataset.goal)):goals.delete(Number(el.dataset.goal));state.goals[state.actualId]=[...goals];save();return;}
 if(el.id==='private-history'){const previous=byId.get(el.value);if(previous){state.privateViewId=previous.id;save();renderWill();}return;}
 if(el.dataset.field==='action'){const row=el.closest('[data-entry]'),entry=currentDraft().entries.find(e=>e.id===row.dataset.entry);entry.action=el.value;const phase=currentRole().template.actionPhases?.[el.value];if(phase)entry.phase=phase;save();renderWill();document.querySelector(`[data-entry="${entry.id}"] [data-field="action"]`)?.focus({preventScroll:true});}
}
document.addEventListener('error',event=>{const img=event.target;if(!(img instanceof HTMLImageElement))return;const fallback=img.dataset.fallback;if(fallback&&img.src!==fallback){img.src=fallback;img.dataset.fallback='';return;}const replacement=document.createElement('span');replacement.className='image-fallback';replacement.setAttribute('aria-hidden','true');replacement.textContent=(img.dataset.roleName||'?').slice(0,2);img.replaceWith(replacement);},true);
async function boot(){try{
 const response=await fetch('./data/roles.json');if(!response.ok)throw new Error('Role library could not load');data=await response.json();roles=data.roles;library=[...roles,...data.states].sort((a,b)=>a.name.localeCompare(b.name));byId=new Map(library.map(r=>[r.id,r]));
 let raw;try{raw=localStorage.getItem(STORAGE_KEY);}catch{storageFailure=true;}
 let recovered=false;try{state=restoreState(raw,library);}catch{state=initialState();recovered=true;try{localStorage.setItem(STORAGE_KEY+':recovery',raw);localStorage.removeItem(STORAGE_KEY);}catch{storageFailure=true;}}
 const hash=decodeURIComponent(location.hash.slice(1));if(byId.has(hash)){selectActual(state,byId.get(hash),library);}
 $('#alignment-filter').innerHTML='<option value="all">All alignments</option>'+[...new Set(roles.map(r=>r.alignment))].map(a=>`<option value="${h(a)}">${h(roles.find(r=>r.alignment===a).alignment_abbreviation)} · ${h(a)}</option>`).join('');
 render();document.addEventListener('click',handleClick);document.addEventListener('input',handleInput);document.addEventListener('change',handleChange);
 $('#detail-toggle').addEventListener('click',()=>{state.detail=!state.detail;state.expanded=[];save();render();$('#detail-toggle').focus({preventScroll:true});});
 $('#theme-toggle').addEventListener('click',()=>{state.theme=state.theme==='dark'?'light':'dark';save();render();$('#theme-toggle').focus({preventScroll:true});});
 $('#new-match').addEventListener('click',()=>$('#reset-dialog').showModal());
 $('#clear-filters').addEventListener('click',()=>{$('#role-search').value='';$('#faction-filter').value='all';$('#alignment-filter').value='all';pickerFilter();$('#role-search').focus();});
 $('#role-picker').addEventListener('click',e=>{if(e.target===$('#role-picker')){const b=$('#role-picker').getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)closePicker();}});
 $('#role-picker').addEventListener('close',()=>{if(pickerOpener?.isConnected){pickerOpener.setAttribute('aria-expanded','false');pickerOpener.focus();}});
 $('#role-picker').addEventListener('keydown',e=>{const buttons=[...$('#picker-results').querySelectorAll('button')];if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();const index=buttons.indexOf(document.activeElement),next=e.key==='ArrowDown'?Math.min(index+1,buttons.length-1):Math.max(0,index-1);buttons[next]?.focus();}else if(e.key==='Enter'&&e.target.id==='role-search'){e.preventDefault();buttons[0]?.click();}});
 if(recovered)toast('Saved data could not load. A recovery copy was kept where storage permits.');
 }catch(error){$('#app').innerHTML='<div class="load-error notice"><strong>The role library could not load.</strong><p>Refresh the page or check your connection. Existing browser drafts have not been changed.</p><button class="button" id="reload-app">Try again</button></div>';$('#reload-app').addEventListener('click',()=>location.reload());console.error(error);}}
boot();
